{"file_path":"src/parse.js","content":"/** URI template parsing into literal and expression parts. */

/** Failure raised while parsing or expanding a template. */
export class UriTemplateError extends Error {
  /**
   * @param {string} message reason
   * @param {number} [index] 0-based index of the `{` that opens the offending expression
   */
  constructor(message, index) {
    super(message);
    this.name = 'UriTemplateError';
    this.index = index;
  }
}

const OPERATORS = new Set(['+', '#', '.', '/', ';', '?', '&']);
const RESERVED_OPERATORS = new Set(['=', ',', '!', '@', '|']);
const NAME_RE = /^(?:[A-Za-z0-9_]|%[0-9A-Fa-f]{2})(?:\.?(?:[A-Za-z0-9_]|%[0-9A-Fa-f]{2}))*$/;
const MODIFIER_RE = /^[1-9][0-9]{0,3}$/;

function parseVariable(spec, openIndex) {
  if (spec === '') throw new UriTemplateError('empty variable specification', openIndex);

  let explode = false;
  let rest = spec;
  if (rest.endsWith('*')) {
    explode = true;
    rest = rest.slice(0, -1);
  }

  let name = rest;
  let maxLength = null;
  let modifierText = null;
  const colonIndex = rest.indexOf(':');
  if (colonIndex !== -1) {
    name = rest.slice(0, colonIndex);
    modifierText = rest.slice(colonIndex + 1);
  }

  if (!NAME_RE.test(name)) {
    throw new UriTemplateError(`invalid variable name '${name}'`, openIndex);
  }

  if (modifierText !== null) {
    if (!MODIFIER_RE.test(modifierText)) {
      throw new UriTemplateError(`invalid prefix modifier ':${modifierText}'`, openIndex);
    }
    maxLength = Number.parseInt(modifierText, 10);
  }

  return { name, explode, maxLength };
}

function parseExpression(content, openIndex) {
  if (content === '') throw new UriTemplateError('empty expression', openIndex);

  const first = content[0];
  let operator = '';
  let rest = content;

  if (RESERVED_OPERATORS.has(first)) {
    throw new UriTemplateError(`reserved operator '${first}'`, openIndex);
  }
  if (OPERATORS.has(first)) {
    operator = first;
    rest = content.slice(1);
  }

  if (rest === '') throw new UriTemplateError('empty variable specification', openIndex);

  const variables = rest.split(',').map((spec) => parseVariable(spec, openIndex));

  return { type: 'expression', operator, variables };
}

/**
 * Split a template into literal and expression parts.
 *
 * @param {string} template template text
 * @returns {({ type: 'literal', value: string } | { type: 'expression', operator: string, variables: object[] })[]}
 *   the parts in order, with adjacent literal text merged
 */
export function parse(template) {
  if (typeof template !== 'string') throw new UriTemplateError('template must be a string');
  if (template === '') return [];

  const parts = [];
  let literalBuf = '';
  let i = 0;
  const len = template.length;

  while (i < len) {
    const c = template[i];
    if (c === '{') {
      if (literalBuf !== '') {
        parts.push({ type: 'literal', value: literalBuf });
        literalBuf = '';
      }
      const closeIndex = template.indexOf('}', i + 1);
      if (closeIndex === -1) {
        throw new UriTemplateError(`unterminated expression at ${i}`, i);
      }
      const content = template.slice(i + 1, closeIndex);
      const expr = parseExpression(content, i);
      parts.push(expr);
      i = closeIndex + 1;
    } else if (c === '}') {
      throw new UriTemplateError(`unexpected '}' at ${i}`, i);
    } else {
      literalBuf += c;
      i += 1;
    }
  }

  if (literalBuf !== '') parts.push({ type: 'literal', value: literalBuf });

  return parts;
}
"}

