import { UriTemplateError, parse } from './parse.js';

const UNRESERVED_RE = /[A-Za-z0-9\-._~]/;
const RESERVED = new Set([
  ':', '/', '?', '#', '[', ']', '@', '!', '$', '&', "'", '(', ')', '*', '+', ',', ';', '=',
]);

const OPERATOR_CONFIG = {
  '': { prefix: '', sep: ',', named: false, ifemp: '', reserved: false },
  '+': { prefix: '', sep: ',', named: false, ifemp: '', reserved: true },
  '#': { prefix: '#', sep: ',', named: false, ifemp: '', reserved: true },
  '.': { prefix: '.', sep: '.', named: false, ifemp: '', reserved: false },
  '/': { prefix: '/', sep: '/', named: false, ifemp: '', reserved: false },
  ';': { prefix: ';', sep: ';', named: true, ifemp: '', reserved: false },
  '?': { prefix: '?', sep: '&', named: true, ifemp: '=', reserved: false },
  '&': { prefix: '&', sep: '&', named: true, ifemp: '=', reserved: false },
};

function encodeChar(chStr) {
  const bytes = Buffer.from(chStr, 'utf8');
  let out = '';
  for (const b of bytes) out += `%${b.toString(16).toUpperCase().padStart(2, '0')}`;
  return out;
}

function encodeValue(str, reserved) {
  let out = '';
  let i = 0;
  while (i < str.length) {
    const c = str[i];
    if (reserved && c === '%' && /^[0-9A-Fa-f]{2}$/.test(str.substr(i + 1, 2))) {
      out += str.substr(i, 3);
      i += 3;
